"""Genera los PDF de datos, pruebas y entrega a partir de los resultados guardados."""
from pathlib import Path
import json,re,textwrap
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,PageBreak,Table,TableStyle,Image,Preformatted
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
BASE=Path(__file__).resolve().parent
DOCS=BASE/'docs';OUT=DOCS/'resultados';C=json.loads((BASE/'entrega.json').read_text(encoding='utf-8'));N=C['actividad']
M=json.loads((OUT/'metricas.json').read_text(encoding='utf-8'));W=A4[0]-144
fontdir=Path('C:/Windows/Fonts')
if (fontdir/'times.ttf').exists():
    for name,file in [('TNR','times.ttf'),('TNRB','timesbd.ttf')]:pdfmetrics.registerFont(TTFont(name,str(fontdir/file)))
    F,B='TNR','TNRB'
else:F,B='Times-Roman','Times-Bold'
body=ParagraphStyle('Cuerpo',fontName=F,fontSize=12,leading=14,spaceAfter=8,firstLineIndent=35.4)
heading=ParagraphStyle('Titulo',fontName=B,fontSize=12,leading=14,alignment=1,spaceBefore=8,spaceAfter=12)
cover=ParagraphStyle('Portada',parent=heading,spaceBefore=0,spaceAfter=8)
small=ParagraphStyle('Tabla',fontName=F,fontSize=10,leading=12,spaceAfter=2)
code=ParagraphStyle('Codigo',fontName='Courier',fontSize=8,leading=10,spaceAfter=8)
def p(t,style=body):return Paragraph(escape(str(t)),style)
def h(t):return p(t,heading)
def link(url,label=None):return Paragraph(f'<link href="{escape(url)}" color="#225566"><u>{escape(label or url)}</u></link>',small)
def page(c,d):c.setFont(F,12);c.drawRightString(A4[0]-72,A4[1]-45,str(d.page))
def build(name,items):SimpleDocTemplate(str(DOCS/name),pagesize=A4,leftMargin=72,rightMargin=72,topMargin=72,bottomMargin=72,title=name.removesuffix('.pdf'),author='Santiago Duque Mora y Geraldine Ríos').build(items,onFirstPage=page,onLaterPages=page)
def portada(tipo):
    return [p('INSTITUCION UNIVERSITARIA IBEROAMERICANA',cover),p('INTELIGENCIA ARTIFICIAL',cover),Spacer(1,20),p(f'Actividad {N} - Métodos de aprendizaje {C["tema"]}',cover),p(tipo,cover),Spacer(1,50),p('Trabajo de:',cover),p('SANTIAGO DUQUE MORA',cover),p('GERALDINE RÍOS',cover),Spacer(1,120),p('Docente:',cover),p('SANDRA ISABEL RODRIGUEZ BAUTISTA',cover),Spacer(1,110),p('Fecha de elaboración:',cover),p(C['fecha_documentacion'],cover),PageBreak()]
def table(rows,widths=None):
    data=[[p(x,small) for x in r] for r in rows]
    t=Table(data,colWidths=widths or [W/len(rows[0])]*len(rows[0]),repeatRows=1,hAlign='CENTER')
    t.setStyle(TableStyle([('GRID',(0,0),(-1,-1),.4,colors.HexColor('#d9d9d9')),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#eeeeee')),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]));return t
def graph(name,width=W,height=None):
    img=Image(str(OUT/name));ratio=img.imageHeight/img.imageWidth;return Image(str(OUT/name),width=width,height=height or width*ratio)

items=portada('Descripción de los datos')+[h('Continuidad y procedencia'),p('En la Actividad 2 se trabajaron las rutas del Metro de Medellín. Esta actividad continúa el proyecto con el análisis de la demanda en ocho estaciones.'),p('Se revisaron el portal de datos abiertos y los metadatos de afluencia del Metro. Para este ejercicio se creó una muestra simulada, ya que no se contó con un archivo verificado que reuniera estación, hora, día, lluvia y evento. El enunciado permite desarrollar una muestra de datos.'),h('Unidad de observación y tamaño'),p(f'Cada fila representa un escenario hipotético de demanda de una estación durante una franja de una hora. Son {M["auditoria"]["filas_originales"]:,} escenarios generados con semilla 42; se retiran {M["auditoria"]["duplicados_eliminados"]} duplicados exactos y se utilizan {M["auditoria"]["filas_utilizadas"]:,} filas. No existe fecha ni secuencia temporal real. El muestreo de horas y días es uniforme, no proporcional al servicio.'),p('Estaciones: '+', '.join(M['auditoria']['estaciones'])+'.'),h('Definición de ocupación'),p('La variable nivel_ocupacion clasifica la demanda: baja hasta 350 pasajeros, media entre 351 y 800 y alta desde 801. Son umbrales definidos para el ejercicio; no representan el porcentaje de ocupación de los trenes.'),PageBreak(),h('Diccionario de datos'),table([['Campo','Tipo y significado'],['estacion','Texto. Una de ocho estaciones del modelo anterior.'],['linea','Texto. Línea A o B de referencia; San Antonio se codifica en A aunque permite transbordo.'],['hora','Entero, 5 a 21. Franja horaria simulada.'],['dia_semana','Entero, 0 lunes a 6 domingo.'],['es_festivo','Binario, probabilidad simulada 0,06. No consulta calendario.'],['lluvia','Binario, probabilidad simulada 0,25.'],['evento_especial','Binario, probabilidad simulada 0,05.'],['pasajeros','Entero ≥20. Conteo simulado por franja; no capacidad.'],['nivel_ocupacion','Etiqueta baja/media/alta según umbrales académicos.']],[120,W-120]),Spacer(1,12),h('Generación reproducible'),p('La base por estación va de 280 a 560. Se multiplica por 2,4 en horas pico laborables (6–8 y 17–19), por 1,2 entre las 10 y las 16 en otros casos y por 0,55 en las restantes franjas. Un día no laborable multiplica por 0,70; lluvia por 0,86; evento por 1,45. Se incorpora ruido lognormal con sigma 0,22 y media aritmética 1. Se redondea y aplica mínimo 20. Todos estos factores son supuestos didácticos sin calibración.'),p('generar_dataset.py conserva la fórmula y las bases de cada estación. dataset_transporte.metadata.json registra semilla, versión de NumPy y SHA-256. Ambas actividades usan exactamente el mismo CSV. La regeneración con las versiones fijadas permite verificar su integridad.'),PageBreak(),h('Uso en el componente'),p('Se emplean estación, línea, hora, día, festivo, lluvia y evento para predecir la clase. pasajeros se excluye porque la etiqueta deriva de él. El preprocesamiento se aprende dentro de cada partición; la prueba final queda separada.' if N==3 else 'K-Means utiliza hora, no_laborable y pasajeros, estandarizados. no_laborable combina fin de semana o festivo. nivel_ocupacion no participa y su columna puede omitirse. El análisis jerárquico usa perfiles agregados por estación.'),h('Límites de interpretación'),p('Los resultados dependen de los supuestos de la simulación. Para aplicarlos al servicio real sería necesario trabajar con mediciones por fecha y estación y comprobar su comportamiento en otros periodos. La comparación entre escenarios con y sin lluvia es descriptiva.'),h('Fuentes consultadas y referencia del curso')]
for label,url in [('Proyecto anterior: estaciones y reglas','https://github.com/Dumo04/actividad2-rutas-metro-medellin'),('Metro de Medellín: transparencia y acceso a datos','https://www.metrodemedellin.gov.co/quienes-somos/transparencia/'),('Metadatos oficiales: afluencia del sistema Metro','https://metrogis.metrodemedellin.gov.co/portal2/sharing/rest/content/items/9180f99f8c18452cb1bca4b2716993db/data'),('scikit-learn: validación cruzada','https://scikit-learn.org/stable/modules/cross_validation.html'),('scikit-learn: agrupamiento','https://scikit-learn.org/stable/modules/clustering.html')]:items.extend([link(url,label),Spacer(1,6)])
items += [p('Consulta de recursos web: 9 de octubre de 2026. Los documentos oficiales se usan como contexto y búsqueda de fuentes; no son el origen de las filas simuladas.'),p('Lectura asignada: Palma Méndez, J. T. (2008). Inteligencia artificial: métodos, técnicas y aplicaciones. McGraw-Hill España. Capítulo '+('17: Aprendizaje de árboles y reglas de decisión.' if N==3 else '16: Técnicas de agrupamiento.')+' Lectura pendiente de revisión.')]
build('Descripcion_datos.pdf',items)

script='modelo.py' if N==3 else 'clustering.py'
items=portada('Pruebas del componente desarrollado')+[h('Ejecución y controles'),p(f'Ejecución real registrada el 9 de octubre de 2026 con Python {M["python"]} y scikit-learn {M["sklearn"]}. Se utilizaron {M["auditoria"]["filas_utilizadas"]} escenarios válidos. Los resultados y las salidas completas están en docs/resultados.'),Preformatted('python '+script+'\npython -m unittest discover -s tests -v',code),p('El programa valida los datos y crea la carpeta de resultados. Se comprueban las columnas, los valores faltantes y los rangos permitidos antes de ejecutar el modelo.'),h('Resultados del experimento')]
if N==3:
    rows=[['Modelo','Accuracy prueba','F1 macro prueba','F1 CV entren.']]
    for name,r in M['modelos'].items():rows.append([name,f'{r["accuracy_test"]:.4f}',f'{r["f1_macro_test"]:.4f}',f'{r["cv_f1_macro_media"]:.4f}'])
    items += [table(rows),Spacer(1,10),p(f'Separación estratificada 80/20: {M["entrenamiento"]} filas de entrenamiento y {M["prueba"]} de prueba. La validación cruzada estratificada de cinco particiones se aplica únicamente al entrenamiento. El bosque se selecciona por el F1 macro medio de validación; no se elige según la prueba final.'),p('El predictor mayoritario sirve como línea base. F1 macro promedia las clases con igual peso; accuracy expresa la proporción total correcta. Se conservan predicciones, particiones y reportes por clase para revisar los errores.'),PageBreak(),h('Matriz de confusión del modelo seleccionado'),graph('matriz_bosque.png',390),p('Las filas representan la clase real y las columnas la predicha. Los errores entre baja y media o media y alta son esperables por el ruido y la ausencia del conteo como predictor. Las matrices de los otros modelos también están guardadas.'),h('Interpretación'),p('El árbol de profundidad máxima 5 permite extraer reglas. La imagen del árbol muestra solo los primeros tres niveles; reglas_arbol.txt contiene la representación hasta profundidad 5. La importancia de variables es propia del árbol y no representa causalidad.')]
else:
    items += [table([['k','Inercia','Silueta']]+[[str(r['k']),f'{r["inercia"]:.2f}',f'{r["silueta"]:.4f}'] for r in M['evaluacion_k']]),Spacer(1,10),p(f'Entre k=2 y k=8, la mayor silueta fue {M["silueta"]:.4f} para k={M["k_elegido"]}. Se calcula sobre una muestra fija de hasta 3.000 filas. Es una selección dentro del intervalo explorado, no un óptimo global demostrado.'),p('El escalado evita que la magnitud de pasajeros domine por sus unidades. No hay clase verdadera de cluster: los identificadores son arbitrarios y no equivalen a baja/media/alta. La variable binaria no_laborable influye mucho en la separación; deben interpretarse sus perfiles.'),PageBreak(),h('Agrupamientos observados'),graph('codo_silueta.png'),Spacer(1,8),table([['Grupo','Hora media','Pasajeros medios','Casos']]+[[str(r['cluster']),f'{r["hora"]:.2f}',f'{r["pasajeros"]:.2f}',str(r['registros'])] for r in M['perfiles']]),Spacer(1,8),p(f'PCA conserva {M["pca_varianza_explicada"]:.1%} de la varianza al proyectar a dos dimensiones; se usa para visualizar, no para entrenar K-Means. Estabilidad con otras semillas (ARI): '+', '.join(f'{r["semilla"]}: {r["ari"]:.4f}' for r in M['estabilidad'])+'.')]
items += [PageBreak(),h('Pruebas automatizadas y evidencia')]
log=(OUT/'pruebas.txt').read_text(encoding='utf-8');cases=re.findall(r'^(test_\S+).*? \.\.\. (ok|FAIL|ERROR)',log,re.M)
items += [p(f'Se ejecutaron {len(cases)} pruebas unitarias. Resultado: '+('todas aprobadas.' if cases and all(s=='ok' for _,s in cases) else 'revisar salida adjunta.')),table([['Prueba','Resultado']]+[[name.removeprefix('test_').replace('_',' '),state] for name,state in cases],[W-70,70]),Spacer(1,12),p('Además, el programa completo terminó con código 0 y generó sus métricas, CSV y gráficas. La evidencia reproducible está en ejecucion.txt y pruebas.txt. Las pruebas verifican comportamiento del software; no certifican exactitud en pasajeros reales.'),h('Criterios y límites'),p('Los conjuntos de entrenamiento y prueba están separados. pasajeros no se utiliza como predictor y el programa acepta categorías nuevas. La evaluación aleatoria corresponde a los escenarios simulados; no mide un pronóstico de días futuros.' if N==3 else 'El componente funciona sin nivel_ocupacion; cambiar esa etiqueta no altera su matriz numérica. Se rechazan perfiles sin muestras suficientes. Ward forma tres grupos por una decisión exploratoria, no porque se haya demostrado que tres sea el mejor número. Las diferencias entre estaciones dependen de parámetros simulados.')]
build('Pruebas_componente.pdf',items)
items=portada('Documento de entrega provisional')+[h('Enlaces de la actividad'),p('Repositorio y documentos correspondientes a la actividad. Los enlaces de los archivos se habilitan al incorporar los cambios a main.'),link(C['repo'],'Repositorio Git de la Actividad '+str(N)),Spacer(1,10)]
for label,path in [('Archivos de datos','dataset_transporte.csv'),('Código fuente Python',script),('Descripción de los datos','docs/Descripcion_datos.pdf'),('Documento de pruebas','docs/Pruebas_componente.pdf')]+([('Mapa conceptual','docs/Mapa_conceptual.pdf')] if N==3 else []):items.extend([link(C['repo']+'/blob/main/'+path,label),Spacer(1,10)])
items += [h('Video explicativo'),link(C['video'],'Video de la actividad') if C.get('video') else p('Pendiente de publicación. El video incluirá la explicación de ambos integrantes y tendrá una duración menor de diez minutos.'),h('Pendientes antes de entregar'),p('Revisar e incorporar los cambios, agregar el enlace del video e invitar a la docente como colaboradora del repositorio. Completar la lectura indicada en el curso.')]
build(f'Entrega_Actividad{N}.pdf',items)
if N==3:
    from reportlab.graphics.shapes import Drawing,Rect,String,Line
    d=Drawing(W,440)
    nodes=[(80,370,290,48,'Aprendizaje supervisado'),(5,265,210,65,'Datos simulados de Medellín'),(235,265,210,65,'Etiqueta baja / media / alta'),(80,160,290,60,'Entrenar árbol y Random Forest'),(80,55,290,60,'Evaluar en casos reservados')]
    for x,y,w,hh,label in nodes:d.add(Rect(x,y,w,hh,fillColor=colors.HexColor('#f5f5f5'),strokeColor=colors.grey));d.add(String(x+w/2,y+hh/2,label,fontName=B,fontSize=11,textAnchor='middle'))
    for x1,y1,x2,y2,label in [(225,370,110,330,'utiliza'),(225,370,340,330,'predice'),(110,265,180,220,'separar 80/20'),(340,265,280,220,'sin usar pasajeros'),(225,160,225,115,'validar y comparar')]:d.add(Line(x1,y1,x2,y2,strokeColor=colors.grey));d.add(String((x1+x2)/2+4,(y1+y2)/2,label,fontName=F,fontSize=9))
    build('Mapa_conceptual.pdf',[h('Actividad 3 - Mapa conceptual'),p('De rutas y reglas de la Actividad 2 a la clasificación de demanda en el mismo transporte.'),d,p('Validación: cinco particiones solo en entrenamiento. Prueba: accuracy, F1 macro y matriz de confusión. Comparación con clase mayoritaria. Interpretación: reglas e importancia del árbol. Límite: los patrones pertenecen a una simulación y requieren validación con datos reales.')])
print(f'PDF de Actividad {N} generados desde métricas verificadas.')
